def emit_invocation(argv: list[str]) -> None:
    emit(
        {
            "type": "fake_invocation",
            "argv": argv,
            "cwd": os.getcwd(),
            "stdin_closed": sys.stdin.read() == "",
            "environment": {
                key: os.environ.get(key)
                for key in (
                    "HOME",
                    "XDG_CONFIG_HOME",
                    "XDG_STATE_HOME",
                    "OVCAQ_FAKE_SCENARIO",
                    "OVCAQ_FAKE_MARKER",
                )
            },
        },
        stderr=argv in (["--version"], ["login", "status"]),
    )


